import urllib.request, sys
URL = "https://raw.githubusercontent.com/prasol/wlx-markdown-viewer/5a9dadd93e537135d2c5b7758fa36b6f5cedd771/experiments/hypergame_g1_hf_compact.py"
source = urllib.request.urlopen(URL, timeout=60).read().decode("utf-8")
start = source.index("def feat(")
end = source.index("def writecsv")
replacement = "def feature_batch(c,gs,ss,oods=None):\n rep,sd,m,op=c\n if oods is None: oods=[False]*len(ss)\n if rep=='raw': return np.stack([raw(g,x,o) for g,x,o in zip(gs,ss,oods)]).astype(np.float32)\n if rep=='hand': return np.stack([hand(g,x,o) for g,x,o in zip(gs,ss,oods)]).astype(np.float32)\n x=np.stack([raw(g,z,o) for g,z,o in zip(gs,ss,oods)]).astype(np.float32)\n with torch.no_grad(): return op.enc(torch.tensor(x,dtype=torch.float32)).numpy().astype(np.float32)\ndef one_step_probs(c,gs,ss,dev,oods=None,batch=2048):\n f=feature_batch(c,gs,ss,oods); out=[]; m=c[2]\n with torch.no_grad():\n  for st in range(0,len(f),batch):\n   x=torch.tensor(f[st:st+batch],dtype=torch.float32,device=dev)[:,None]\n   a=torch.full((len(x),1),BOS,dtype=torch.long,device=dev); r=torch.zeros((len(x),1),dtype=torch.float32,device=dev)\n   out.append(torch.softmax(m(x,a,r)[:,-1],-1).cpu().numpy())\n return np.concatenate(out,0)\ndef sampled_states(g,n,sd,ood=False):\n r=np.random.default_rng(sd);ss=[]\n for _ in range(n):\n  x=reset(g,r,ood)\n  for j in range(int(r.integers(0,max(1,pars(g,ood)['max']//3])))):\n   x,_,d,_=step(g,x,int(r.choice(A)),ood)\n   if d:x=reset(g,r,ood);break\n  ss.append(x)\n return ss\ndef state_group(cands,methods,g,n,sd,dev,ood=False):\n ss=sampled_states(g,n,sd,ood);gs=[g]*n;oo=[ood]*n;P=np.stack([one_step_probs(c,gs,ss,dev,oo) for c in cands]);Y=np.array([ai(oracle(g,x,ood)) for x in ss]);res={}\n for name,_,w in methods:\n  p=np.tensordot(w,P,axes=(0,0));pred=p.argmax(1);acc=float((pred==Y).mean());nll=float((-np.log(np.clip(p[np.arange(n),Y],1e-8,1))).mean());one=np.eye(3)[Y];br=float(((p-one)**2).mean());rg=[]\n  for x,k,y in zip(ss,pred,Y):\n   sp,_,_,_=step(g,x,av(int(k)),ood);so,_,_,_=step(g,x,oracle(g,x,ood),ood);rg.append(max(0,progress(g,so,ood)-progress(g,sp,ood)))\n  res[name]=(acc,nll,br,float(np.mean(rg)))\n return res\ndef rollout_group(cands,methods,g,n,sd,dev,ood=False):\n rng=np.random.default_rng(sd);base=[reset(g,rng,ood) for _ in range(n)];states=[];mid=[]\n for mi in range(len(methods)):\n  for x in base: states.append(x.copy());mid.append(mi)\n M=len(states);done=np.zeros(M,bool);succ=np.zeros(M,float);rets=np.zeros(M,float);ah=[[BOS] for _ in range(M)];rh=[[0.] for _ in range(M)];fh=[[[] for _ in range(M)] for _ in cands]\n for t in range(pars(g,ood)['max']):\n  ids=np.flatnonzero(~done)\n  if not len(ids):break\n  CP=[]\n  for ci,c in enumerate(cands):\n   fb=feature_batch(c,[g]*len(ids),[states[j] for j in ids],[ood]*len(ids))\n   for k,j in enumerate(ids): fh[ci][j].append(fb[k])\n   T=min(t+1,c[2].ctx);x=np.stack([np.stack(fh[ci][j][-T:]) for j in ids]).astype(np.float32);aa=np.stack([np.array(ah[j][-T:],np.int64) for j in ids]);rr=np.stack([np.array(rh[j][-T:],np.float32) for j in ids]);out=[]\n   with torch.no_grad():\n    for st in range(0,len(ids),512):\n     xt=torch.tensor(x[st:st+512],dtype=torch.float32,device=dev);at=torch.tensor(aa[st:st+512],dtype=torch.long,device=dev);rt=torch.tensor(rr[st:st+512],dtype=torch.float32,device=dev);out.append(torch.softmax(c[2](xt,at,rt)[:,-1],-1).cpu().numpy())\n   CP.append(np.concatenate(out,0))\n  CP=np.stack(CP)\n  for q,j in enumerate(ids):\n   w=methods[mid[j]][2];ix=int(np.tensordot(w,CP[:,q],axes=(0,0)).argmax());ns,re,d,su=step(g,states[j],av(ix),ood);states[j]=ns;rets[j]+=re;ah[j].append(ix);rh[j].append(re)\n   if d:done[j]=1;succ[j]=float(su)\n res={}\n for mi,(name,_,_) in enumerate(methods):\n  z=np.array(mid)==mi;res[name]=(float(succ[z].mean()),float(rets[z].mean()))\n return res\ndef hus(cands,train_games,cfg,dev,sd):\n r=np.random.default_rng(sd);gs=[];ss=[]\n for g in train_games:\n  for _ in range(cfg['anchors']//3):gs.append(g);ss.append(reset(g,r))\n Y=np.array([ai(oracle(g,x)) for g,x in zip(gs,ss)]);D=[];O=[]\n for c in cands:\n  p=one_step_probs(c,gs,ss,dev);pred=p.argmax(1);D.append(p.reshape(-1));er=(pred!=Y).mean();bi=((p-np.eye(3)[Y])**2).mean();re=[]\n  for g,x,k in zip(gs,ss,pred):\n   sp,_,_,_=step(g,x,av(int(k)));so,_,_,_=step(g,x,oracle(g,x));re.append(max(0,progress(g,so)-progress(g,sp)))\n  O.append([er,bi,np.mean(re)])\n O=np.array(O);lo=np.percentile(O,5,0);hi=np.percentile(O,95,0);ON=np.clip((O-lo)/np.where(hi-lo>1e-8,hi-lo,1),-1,2);D=np.array(D);D-=D.mean(1,keepdims=True);D/=np.linalg.norm(D,axis=1,keepdims=True)+1e-8;dz=np.linalg.norm(D[:,None]-D[None,:],axis=-1)/math.sqrt(D.shape[1]);do=np.linalg.norm(ON[:,None]-ON[None,:],axis=-1)/math.sqrt(3);sz=np.median(dz[np.triu_indices(len(cands),1)]);so=np.median(do[np.triu_indices(len(cands),1)]);K=np.exp(-.5*(dz/max(sz,1e-6))**2-1.5*.5*(do/max(so,1e-6))**2);np.fill_diagonal(K,0);deg=K.sum(1);K/=np.sqrt((deg[:,None]+1e-8)*(deg[None,:]+1e-8));E=ON@np.array([.55,.25,.2]);E=(E-E.min())/max(1e-8,E.max()-E.min());H=np.diag(E)-.55*K;la,V=np.linalg.eigh(H);q=V@(np.exp(-4*(la-la.min()))*(V.T@(np.ones(len(cands))/math.sqrt(len(cands)))));q=q*q;q/=q.sum();sc=np.exp(-4*E);sc/=sc.sum();top=np.zeros(len(cands));top[E.argmin()]=1;return q,sc,top,E,O,len(cands)*len(ss)*3\n\n"
source = source[:start] + replacement + source[end:]
old = "dmo,pmo=op_metric(op,hold,cfg['op_eval'],800+fi,dev,True);orows.append("
new = "dmo,pmo=op_metric(op,hold,cfg['op_eval'],800+fi,dev,True);op=op.cpu();orows.append("
if old not in source: raise RuntimeError("device patch point not found")
source = source.replace(old,new,1)
old_eval = """  for name,sd,w in methods:
   for dist,ood in [('id',False),('ood',True)]:
    ac,ce,br,rg=eval_states(C,w,hold,cfg['states'],2000+fi+sd+(100 if ood else 0),dev,ood);su,re=rollout(C,w,hold,cfg['roll'],3000+fi+sd+(100 if ood else 0),dev,ood);rows.append(dict(holdout=hold,distribution=dist,method=name,seed=sd,action_acc=ac,nll=ce,brier=br,progress_regret=rg,rollout_success=su,return_mean=re))
"""
new_eval = """  for dist,ood in [('id',False),('ood',True)]:
   for sd in cfg['seeds']:
    group=[m for m in methods if m[1]==sd];sm=state_group(C,group,hold,cfg['states'],2000+fi+sd+(100 if ood else 0),dev,ood);rm=rollout_group(C,group,hold,cfg['roll'],3000+fi+sd+(100 if ood else 0),dev,ood)
    for name,_,w in group:
     ac,ce,br,rg=sm[name];su,re=rm[name];rows.append(dict(holdout=hold,distribution=dist,method=name,seed=sd,action_acc=ac,nll=ce,brier=br,progress_regret=rg,rollout_success=su,return_mean=re))
"""
if old_eval not in source: raise RuntimeError("eval patch point not found")
source=source.replace(old_eval,new_eval,1)
old_art=" print('ARTIFACT_B64='+base64.b64encode(buf.getvalue()).decode(),flush=True)"
new_art=" enc=base64.b64encode(buf.getvalue()).decode()\n for j in range(0,len(enc),3000): print(f'ARTIFACT_{j//3000:03d}='+enc[j:j+3000],flush=True)"
if old_art not in source: raise RuntimeError("artifact patch point not found")
